// Operator-only test input. Never map untrusted mail headers to sender_verified.
const config = {
  edition: 'synthetic', // synthetic or development_store (read/draft only)
  shopify_url: 'http://127.0.0.1:19091/admin/api/2026-10/graphql.json',
  talon_url: 'http://127.0.0.1:8080',
  provider: 'openai',
  model: 'gpt-4o-mini'
};
const email = {
  ticket_id: 'SUP-1001',
  sender: 'buyer@example.test',
  sender_verified: true, // synthetic fixture or attestation by trusted support operator
  subject: 'Order #1001 status',
  body: 'When will my order #1001 arrive?'
};
return {json:{config,email}};

const {config:c,email:e}=$json;
const stop=reason=>({json:{ready:'no',status:'manual_review',reason,refund_execution:'unavailable',message_sent:false}});
if (!c || !['synthetic','development_store'].includes(c.edition)) throw new Error('Choose a supported read-only edition');
if (c.edition==='synthetic' ? !/^http:\/\/127\.0\.0\.1:\d{1,5}\/admin\/api\/2026-10\/graphql\.json$/.test(c.shopify_url) : !/^https:\/\/[a-z0-9][a-z0-9-]*\.myshopify\.com\/admin\/api\/2026-10\/graphql\.json$/.test(c.shopify_url)) throw new Error('Configure the permitted Shopify endpoint for this edition');
if (!/^(?:https:\/\/[a-zA-Z0-9.-]+(?::\d+)?|http:\/\/127\.0\.0\.1:\d+)$/.test(c.talon_url) || !['openai','local-llama'].includes(c.provider) || !/^[a-zA-Z0-9._:-]{1,100}$/.test(c.model)) throw new Error('Configure a trusted Talon endpoint and approved model route');
if (!e || !/^[A-Z]{1,10}-[0-9]{1,12}$/.test(e.ticket_id||'') || e.sender_verified!==true || typeof e.sender!=='string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e.sender) || typeof e.subject!=='string' || typeof e.body!=='string' || e.subject.length>500 || e.body.length>8000) return stop('requester_or_input_unverified');
if(c.edition==='synthetic'&&!e.sender.toLowerCase().endsWith('.test'))return stop('synthetic_only');
const message=e.subject+' '+e.body;
const orders=[...new Set((message.match(/#[0-9]{1,12}\b/g)||[]))];
if(orders.length!==1)return stop('one_order_number_required');
const hints=[];
for(const [name,re] of [['refund_request',/\b(refund|money back|duplicate charge)\b/i],['damaged_product',/\b(damaged|broken|defective)\b/i],['incorrect_product',/\b(wrong|incorrect)\b/i],['return_request',/\b(return|exchange)\b/i],['shipping_delay',/\b(delay|late|not arrived|missing delivery)\b/i],['order_status',/\b(status|track|arrive|shipping|delivery|where)\b/i]])if(re.test(message))hints.push(name);
if(!hints.length)return stop('unsupported_issue');
const amounts=[...new Set([...message.matchAll(/\bEUR\s+(\d{1,7}(?:\.\d{1,2})?)(?![\d.,])/gi)].map(m=>m[1]))];
return {json:{ready:'yes',ticket_id:e.ticket_id,requester:e.sender.trim().toLowerCase(),order_name:orders[0],hints,requested_amount:amounts.length===1?amounts[0]:null,session_id:'shopify-support-'+String($execution.id),edition:c.edition}};

const q=$('Prepare request').first().json;
const stop=reason=>({json:{ready:'no',status:'manual_review',reason,session_id:q.session_id,refund_execution:'unavailable',message_sent:false}});
const b=$json.body;
if($json.statusCode!==200||!b||b.errors?.length)return stop('shopify_lookup_failed');
const conn=b.data?.orders;
const o=conn?.nodes?.length===1&&!conn.pageInfo?.hasNextPage?conn.nodes[0]:null;
if(!o||o.name!==q.order_name||typeof o.email!=='string'||o.email.trim().toLowerCase()!==q.requester||o.test!==true)return stop('order_or_requester_not_verified');
const money=m=>{
 if(m?.currencyCode!=='EUR'||typeof m.amount!=='string'||!/^(0|[1-9]\d{0,8})(\.\d{1,2})?$/.test(m.amount))return null;
 const [a,f='']=m.amount.split('.');return Number(a)*100+Number(f.padEnd(2,'0'));
};
const received=money(o.totalReceivedSet?.presentmentMoney),refunded=money(o.totalRefundedSet?.presentmentMoney);
const request=money({amount:q.requested_amount,currencyCode:'EUR'});
const validFinancial=['PAID','PARTIALLY_REFUNDED','REFUNDED','PENDING','AUTHORIZED','PARTIALLY_PAID','VOIDED','EXPIRED'];
const validFulfillment=['FULFILLED','UNFULFILLED','PARTIALLY_FULFILLED','IN_PROGRESS','ON_HOLD','OPEN','PENDING_FULFILLMENT','REQUEST_DECLINED','RESTOCKED','SCHEDULED'];
if(!validFinancial.includes(o.displayFinancialStatus)||!validFulfillment.includes(o.displayFulfillmentStatus))return stop('unsupported_order_status');
let candidate=null;
if(q.hints.includes('refund_request')&&received!==null&&refunded!==null&&request!==null&&request>0&&request<=received-refunded&&['PAID','PARTIALLY_REFUNDED'].includes(o.displayFinancialStatus)){
  candidate=request; // arithmetic screening only; not merchant eligibility or authorization
}
const facts={issue_hints:q.hints,financial_status:o.displayFinancialStatus,fulfillment_status:o.displayFulfillmentStatus,proposed_refund_eur:candidate===null?null:(Math.floor(candidate/100)+'.'+String(candidate%100).padStart(2,'0'))};
return {json:{ready:'yes',session_id:q.session_id,ticket_id:q.ticket_id,edition:q.edition,facts,refund_screen:q.hints.includes('refund_request')?(candidate===null?'manual_review':'amount_screen_passed_eligibility_unverified'):'not_requested'}};

const source=$('Verify order and minimize').first().json;
const stop=reason=>({json:{status:'manual_review',reason,session_id:source.session_id,refund_execution:'unavailable',message_sent:false}});
if($json.statusCode!==200)return stop('model_request_not_successful');
const raw=$json.body?.choices?.[0]?.message?.content;
if(typeof raw!=='string'||raw.length>4000)return stop('invalid_model_response');
let v;try{v=JSON.parse(raw);}catch{return stop('invalid_model_json');}
if(!v||Array.isArray(v)||Object.keys(v).sort().join(',')!=='draft,issue,proposed_refund_eur,recommendation'||!source.facts.issue_hints.includes(v.issue)||!['status_reply','refund_review','manual_review'].includes(v.recommendation)||typeof v.draft!=='string'||v.draft.trim().length<10||v.draft.length>800||/@|https?:|\b(?:refund(?:ed| (?:was |has been )?(?:completed|processed|issued|sent|approved))|money (?:was |has been )?returned)\b/i.test(v.draft))return stop('model_output_needs_review');
if(v.recommendation==='refund_review'?(source.facts.proposed_refund_eur===null||v.proposed_refund_eur!==source.facts.proposed_refund_eur):v.proposed_refund_eur!==null)return stop('invalid_refund_recommendation');
if(v.recommendation==='status_reply'&&(!['order_status','shipping_delay'].includes(v.issue)||source.facts.issue_hints.some(x=>!['order_status','shipping_delay'].includes(x))))return stop('merchant_review_required');
if(source.refund_screen==='manual_review'&&v.recommendation!=='manual_review')return stop('merchant_review_required');
return {json:{status:'draft_ready_for_operator_review',session_id:source.session_id,ticket_id:source.ticket_id,edition:source.edition,order_facts:source.facts,issue:v.issue,recommendation:v.recommendation,proposed_refund_eur:v.proposed_refund_eur,merchant_eligibility:'not_established',draft:v.draft.trim(),draft_is_untrusted:true,refund_execution:'unavailable',message_sent:false}};
